import os
import json
import moler.config as config  # type: ignore
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.post import PostRunner
from taf.ul.sc.perf.util.logger import log_debug_function_info


@log_debug_function_info()
def make_bin_directory():
    unix_local = UnixFunctionality(device_name="UnixLocal", autoconnect=True)
    unix_local.make_directory(path=os.path.join(tc.output_dir, "bin"))


@log_debug_function_info()
def save_run_params_to_json_file():
    file_path = os.path.join(tc.output_dir, "bin", "run_params.json")
    data = json.dumps(tc.run_params, sort_keys=True, indent=4)
    with open(file_path, 'w') as output_file:
        output_file.write(data)


@log_debug_function_info()
def save_execution_stats_to_json_file():
    file_path = os.path.join(tc.output_dir, "bin", "execution_stats.json")
    data = json.dumps(tc.stats, sort_keys=True, indent=4)
    with open(file_path, 'w') as output_file:
        output_file.write(data)


@log_debug_function_info()
def save_moler_configuration_to_json_file():
    file_path = os.path.join(tc.output_dir, "bin", "moler_config.json")
    data = json.dumps(config.loaded_config, sort_keys=True, indent=4)
    with open(file_path, 'w') as output_file:
        output_file.write(data)


@log_debug_function_info()
def run_post_process():
    pa = PostRunner()
    post_type = tc.run_params['post_process']['type']
    if post_type == 'background':
        pa.run_post_process_in_the_background()
    elif post_type == 'foreground':
        pa.run_post_process_in_the_foreground()
    elif post_type == 'ute_cloud_manager':
        pa.run_post_process_for_cm()
    else:
        raise Exception('[{}] is not supported type of post processing'.format(post_type))
